@import "@fontsource-variable/manrope";
@import "@fontsource-variable/fraunces";

:root{--organic-white:#fff;--organic-avatar-1:#687060;--organic-avatar-2:#30392c;--organic-avatar-3:#859379;--organic-avatar-4:#4b5945;--organic-chart-bar:#6f8b56;--organic-brand:#11180e;--organic-brand-mark:#9dbf73}
:where([data-slot="switch"])[data-state="unchecked"]{background:var(--border)}
.custom-preview-wide{width:min(100%,1080px)}
.custom-preview-medium{width:min(100%,700px)}
.custom-preview-dashboard{width:100%;min-width:920px}
.organic-kicker{margin:0 0 10px;color:var(--primary);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.workshop-schedule{padding:clamp(24px,4vw,54px);border:1px solid color-mix(in srgb,var(--border) 72%,transparent);border-radius:44px;background:var(--card);box-shadow:0 20px 52px rgba(25,35,21,.12)}
.schedule-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:32px;margin-bottom:40px}
.schedule-heading h2,.engagement-heading h2{margin:0;font-size:clamp(32px,4vw,54px);max-width:13ch}
.schedule-heading h2 span{display:block}
.schedule-stats{display:flex;align-items:stretch;gap:30px}
.schedule-stats p{display:grid;grid-template-columns:auto minmax(80px,110px);align-items:center;gap:12px;margin:0;padding-left:30px;border-left:1px solid var(--border)}
.schedule-stats p:first-child{border-left:0}
.schedule-stats strong{font-size:38px;line-height:1;font-variant-numeric:tabular-nums}
.schedule-stats span{color:var(--muted-foreground);font-size:13px;line-height:1.25}
.schedule-table{display:grid;gap:10px}
.schedule-header,.schedule-row{display:grid;grid-template-columns:minmax(190px,1.35fr) minmax(160px,1.1fr) 130px 126px 150px 46px;align-items:center;gap:20px}
.schedule-header{padding:0 20px 8px;color:var(--muted-foreground);font-size:12px}
.schedule-row{min-height:84px;padding:12px 14px 12px 20px;border-radius:999px;background:var(--muted);transition:background var(--motion-duration) var(--motion-easing)}
.schedule-row:nth-child(even){background:var(--organic-white)}
.schedule-row:hover{background:var(--secondary)}
.instructor{display:flex;align-items:center;gap:14px;min-width:0}
.instructor>span:last-child{display:grid;min-width:0}
.instructor strong,.module{font-size:15px;font-weight:650}
.instructor small,.date-cell small,.time-cell small{color:var(--muted-foreground);font-size:12px}
.avatar-tone{display:grid;width:48px;height:48px;flex:0 0 48px;place-items:center;border:1px solid rgba(25,35,21,.1);border-radius:50%;color:var(--organic-white);font-family:var(--font-heading);font-size:18px}
.avatar-tone-1{background:var(--organic-avatar-1)}.avatar-tone-2{background:var(--organic-avatar-2)}.avatar-tone-3{background:var(--organic-avatar-3)}.avatar-tone-4{background:var(--organic-avatar-4)}
.module{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.level-pill{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border:1px solid var(--border);border-radius:999px;background:var(--organic-white);box-shadow:0 2px 6px rgba(25,35,21,.06);font-size:13px;font-weight:600}
.level-pill svg,.time-cell svg{width:16px;height:16px;color:var(--muted-foreground)}
.date-cell,.time-cell{font-size:14px;font-variant-numeric:tabular-nums}.date-cell small,.time-cell small{display:none}
.time-cell{display:flex;align-items:center;gap:8px}
.engagement-card{min-height:460px;padding:36px;border-radius:36px;background:var(--accent);color:var(--accent-foreground);box-shadow:0 16px 40px rgba(25,35,21,.1)}
.engagement-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}
.engagement-heading h2{font-size:36px}.engagement-heading .organic-kicker{color:var(--accent-foreground);opacity:.68}
.range-tabs{display:flex;padding:4px;border:1px solid color-mix(in srgb,var(--accent-foreground) 16%,transparent);border-radius:999px;background:rgba(255,255,255,.18)}
.range-tabs button{min-width:50px;height:38px;border:0;border-radius:999px;background:transparent;color:var(--accent-foreground);font-size:13px;font-weight:650;cursor:pointer}
.range-tabs button.active{background:var(--primary);color:var(--primary-foreground);box-shadow:0 3px 10px rgba(25,35,21,.14)}
.bar-chart{display:grid;grid-template-columns:repeat(5,1fr);align-items:end;gap:22px;height:290px;margin-top:30px;padding-top:20px;border-top:1px dashed rgba(25,35,21,.18)}
.bar-column{display:grid;justify-items:center;gap:12px;height:100%;grid-template-rows:1fr auto}
.bar-track{position:relative;width:40px;height:100%;overflow:hidden;border-radius:999px;background:rgba(255,255,255,.26)}
.bar-value{position:absolute;inset:auto 0 0;border-radius:999px;background:var(--organic-chart-bar);transition:height 300ms var(--motion-easing)}
.bar-column.is-highlight .bar-value{background:var(--primary)}
.bar-value b{position:absolute;top:12px;left:50%;transform:translateX(-50%);color:var(--organic-white);font-size:13px}
.bar-column small{font-size:13px;font-weight:600}
.brand-focus{position:relative;min-height:460px;overflow:hidden;padding:38px;border-radius:36px;background:var(--organic-brand);color:var(--organic-white);box-shadow:0 16px 40px rgba(25,35,21,.18)}
.brand-mark{position:relative;z-index:2;display:flex;align-items:center;gap:10px;font-size:16px}.brand-mark span{color:var(--organic-brand-mark);font-size:22px}
.brand-focus h2{position:relative;z-index:2;margin:82px 0 0;font-size:clamp(44px,5.5vw,74px);line-height:.95}
.network-orb{position:absolute;right:-70px;bottom:-90px;width:360px;height:360px;border:1px solid rgba(255,255,255,.08);border-radius:50%;background:repeating-radial-gradient(circle at 50% 50%,transparent 0 42px,rgba(255,255,255,.045) 43px 44px),repeating-linear-gradient(35deg,transparent 0 36px,rgba(255,255,255,.035) 37px 38px)}
.network-orb span{position:absolute;width:7px;height:7px;border-radius:50%;background:#f7f8f2;box-shadow:0 0 16px rgba(255,255,255,.7)}
.network-orb span:nth-child(1){left:20%;top:24%}.network-orb span:nth-child(2){left:46%;top:12%}.network-orb span:nth-child(3){left:70%;top:30%}.network-orb span:nth-child(4){left:31%;top:56%}.network-orb span:nth-child(5){left:61%;top:64%}.network-orb span:nth-child(6){left:82%;top:55%}.network-orb span:nth-child(7){left:42%;top:82%}.network-orb span:nth-child(8){left:14%;top:74%}
.brand-actions{position:absolute;z-index:2;left:38px;bottom:34px;display:flex;align-items:center;gap:10px}.brand-actions button{border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.06);color:var(--organic-white)}.brand-actions p{margin:0 0 0 12px;color:rgba(255,255,255,.58);font-size:12px;line-height:1.45}
.ecosystem-dashboard{display:grid;gap:24px;width:100%;padding:24px;background:var(--background)}
.dashboard-lower{display:grid;grid-template-columns:1.15fr .85fr;gap:24px}.dialog-note{margin:0;color:var(--muted-foreground);font-size:14px}
@media(max-width:900px){.custom-preview-dashboard{min-width:0}.schedule-heading{display:grid}.schedule-stats{justify-content:space-between}.schedule-stats p{flex:1}.schedule-header{display:none}.schedule-row{grid-template-columns:1fr auto;gap:16px;border-radius:24px;padding:18px}.schedule-row .module{grid-column:1/-1;grid-row:1}.schedule-row .instructor{grid-column:1;grid-row:2}.schedule-row>div:nth-child(3){grid-column:2;grid-row:2}.date-cell{grid-column:1;grid-row:3}.time-cell{grid-column:2;grid-row:3}.schedule-row>div:last-child{position:absolute;right:12px;top:10px}.schedule-row{position:relative}.date-cell small,.time-cell small{display:block}.dashboard-lower{grid-template-columns:1fr}.brand-focus,.engagement-card{min-height:420px}}
@media(max-width:560px){.workshop-schedule{padding:24px 18px;border-radius:30px}.schedule-heading{margin-bottom:26px}.schedule-stats{gap:12px}.schedule-stats p{display:block;padding-left:14px}.schedule-stats p:first-child{border-left:1px solid var(--border)}.schedule-stats strong{display:block;font-size:28px;margin-bottom:6px}.schedule-row{grid-template-columns:1fr auto}.instructor small{max-width:20ch}.date-cell,.time-cell{font-size:13px}.engagement-card,.brand-focus{padding:26px;border-radius:30px}.engagement-heading{display:grid}.engagement-heading h2{font-size:32px}.bar-chart{gap:10px;height:240px}.bar-track{width:30px}.brand-focus h2{margin-top:70px;font-size:48px}.brand-actions{left:26px;bottom:26px}.ecosystem-dashboard{padding:12px;gap:16px}.dashboard-lower{gap:16px}}
